void rsr_state_gwr_on(void)
{
  if((RSR_ENGINE_RUNNING || (TACHLESS && rsr_vars.ign) || RSR_CUR_TIME >= RSR_GWR_TO_ACC_TIMEOUT) && cmd_q_insert (INPUT_RS_ACCESSORY | INPUT_ON, RSR_CMD_INSERT_TIMEOUT))
    {        
      #if RSR_ACC_ENA == 1
	    RSR_ACC_SET ;
	  #endif
      rsr_set_state   (RSR_STATE_ACC) ;     	
    }
}


